INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d89dc321-328c-47a9-a97f-e72def107fe9', 1, 'pilula_a', 'por que abrir o olho', 'a maioria dos problemas ambientais está escondida na rotina. o primeiro passo é treinar o olhar pra perceber o que normalmente passa batido.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d89dc321-328c-47a9-a97f-e72def107fe9', 2, 'pilula_b', 'observação > opinião', 'antes de propor, observa. quem vive o problema? em que ritmo? que recurso entra e sai? observação dá lastro pra qualquer ideia depois.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d89dc321-328c-47a9-a97f-e72def107fe9', 3, 'pilula_c', 'o caderno de campo', 'durante a eletiva tu vai anotar muito. um caderno (físico ou digital) com data, lugar, observação. simples e disciplinado.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d89dc321-328c-47a9-a97f-e72def107fe9', 4, 'exercicio_pbl', 'exercício · 1 hora observando', 'escolhe 1 lugar do teu cotidiano (cozinha, escola, mercado). observa por 1 hora sem mexer no celular. anota tudo: o que entra, o que sai, quem age.', 60, 75, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d89dc321-328c-47a9-a97f-e72def107fe9', 5, 'registro', 'registro', 'o que tu viu hoje que tu nunca tinha visto antes?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7dd1ad90-6936-417d-8991-72cbb382cded', 1, 'pilula_a', 'o conceito de vazamento', 'vazamento é tudo que sai do sistema sem propósito: comida no lixo, energia ligada à toa, papel impresso e jogado, água escorrendo.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7dd1ad90-6936-417d-8991-72cbb382cded', 2, 'pilula_b', 'por que a gente não vê', 'o cotidiano normaliza. tu cresceu vendo daquele jeito, então parece natural. o trabalho é desnaturalizar.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7dd1ad90-6936-417d-8991-72cbb382cded', 3, 'pilula_c', 'mapeando 1 ambiente', 'pega 1 cômodo da tua casa. lista tudo que vira lixo numa semana. organiza em 3 colunas: orgânico, reciclável, "tem como evitar?".', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7dd1ad90-6936-417d-8991-72cbb382cded', 4, 'exercicio_pbl', 'exercício · meu mapa', 'desenha (mesmo que feio) o mapa de vazamentos da tua casa ou da tua escola. fotografa e publica no link.', 30, 45, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7dd1ad90-6936-417d-8991-72cbb382cded', 5, 'registro', 'registro', 'qual vazamento te chocou mais? por quê?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('02fe9a42-6b12-407e-9334-147d3c046f7e', 1, 'pilula_a', 'input e output', 'todo sistema tem entrada (recurso) e saída (resíduo ou produto). circular é fechar o ciclo: saída de um vira entrada de outro.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('02fe9a42-6b12-407e-9334-147d3c046f7e', 2, 'pilula_b', 'exemplo simples: o cafezinho', 'entra: água, café, energia, copo. sai: borra, copo descartado, vapor. quanto disso já vira insumo de outro processo? quase nada.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('02fe9a42-6b12-407e-9334-147d3c046f7e', 3, 'pilula_c', 'escala importa', 'tu pode mapear sistêmico do teu lanche, da tua escola, da tua cidade. o método é o mesmo. começa pequeno pra entender.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('02fe9a42-6b12-407e-9334-147d3c046f7e', 4, 'exercicio_pbl', 'exercício · sistema do teu lanche', 'escolhe 1 lanche que tu come com frequência. mapeia: o que entra (insumos, embalagens, transporte) e o que sai (resto, embalagem, gordura). publica.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('02fe9a42-6b12-407e-9334-147d3c046f7e', 5, 'registro', 'registro', 'qual saída do teu lanche poderia virar entrada de outra coisa?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8c71dbda-2fe4-4981-86a3-37b8600ea9ef', 1, 'pilula_a', 'externalidades', 'externalidade é o custo que sobra pra terceiros: ar poluído, rio sujo, trabalhador exposto. preço da prateleira não inclui.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8c71dbda-2fe4-4981-86a3-37b8600ea9ef', 2, 'pilula_b', 'quem paga', 'quase sempre paga quem está mais longe da decisão: comunidade no entorno, próxima geração, ecossistema. injustiça invisível.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8c71dbda-2fe4-4981-86a3-37b8600ea9ef', 3, 'pilula_c', 'tornando visível', 'mostrar a externalidade já é meia batalha. dado, foto, depoimento, mapa. o que tu consegue tornar palpável?', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8c71dbda-2fe4-4981-86a3-37b8600ea9ef', 4, 'exercicio_pbl', 'exercício · investiga 1 produto', 'escolhe 1 produto que tu usa muito. pesquisa: quem produz, onde, quem é impactado pela produção. faz 1 página de achados.', 30, 45, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8c71dbda-2fe4-4981-86a3-37b8600ea9ef', 5, 'registro', 'registro', 'tu seguiria comprando esse produto? mudaria algo na tua escolha?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('b83924a0-91e5-4549-a976-041ca6b28651', 1, 'pilula_a', 'o que é campo de observação', 'campo é o recorte: lugar + ator + problema. quanto mais nítido, melhor as próximas fases. campo amplo demais paralisa.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('b83924a0-91e5-4549-a976-041ca6b28651', 2, 'pilula_b', 'escolhendo bem', 'um campo bom: tu tem acesso, tu se importa, tem gente sentindo o problema, dá pra propor algo concreto em 8 semanas.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('b83924a0-91e5-4549-a976-041ca6b28651', 3, 'pilula_c', 'escrevendo em 3 frases', 'lugar, ator, problema percebido. ex: "no refeitório da escola, alunos do ensino médio descartam X kg de comida por dia".', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('b83924a0-91e5-4549-a976-041ca6b28651', 4, 'exercicio_pbl', 'exercício · meu campo definido', 'escreve teu campo em 3 frases. junta 3 fotos ou desenhos do lugar. publica no link.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('b83924a0-91e5-4549-a976-041ca6b28651', 5, 'registro', 'registro', 'por que esse campo e não outro? o que te puxou pra aí?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('29e2d414-53ad-494f-8856-3d4a7caed582', 1, 'pilula_a', 'linear: extrair, usar, descartar', 'modelo dominante. extrai recurso, faz produto, vende, descarta. é eficiente em escala mas insustentável em ciclo longo.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('29e2d414-53ad-494f-8856-3d4a7caed582', 2, 'pilula_b', 'circular: 3 princípios', 'eliminar resíduo desde o design, manter material em uso o máximo possível, regenerar sistemas naturais. ordem importa.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('29e2d414-53ad-494f-8856-3d4a7caed582', 3, 'pilula_c', 'exemplos vivos', 'natura recicla embalagem, fast-fashion vira aluguel, restaurante vira cozinha-zero-resíduo. ideia já roda no mundo.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('29e2d414-53ad-494f-8856-3d4a7caed582', 4, 'exercicio_pbl', 'exercício · circulariza teu campo', 'aplica os 3 princípios ao teu campo de observação. lista 3 ideias (1 por princípio) de como ele poderia ser circular.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('29e2d414-53ad-494f-8856-3d4a7caed582', 5, 'registro', 'registro', 'qual princípio te puxa mais? por quê?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8bfb2523-7c75-4436-859b-1cc0a547cfd0', 1, 'pilula_a', 'além de causa única', 'problema complexo raramente tem 1 causa. tem rede de causas que se reforçam. pensar em loop ajuda a enxergar.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8bfb2523-7c75-4436-859b-1cc0a547cfd0', 2, 'pilula_b', 'loops de reforço e equilíbrio', 'reforço: quanto mais A, mais B, mais A (espiral). equilíbrio: A sobe, B sobe e puxa A pra baixo (regula). reconhecer o tipo abre estratégia.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8bfb2523-7c75-4436-859b-1cc0a547cfd0', 3, 'pilula_c', 'mapeando 1 loop', 'desenha 3 a 5 elementos do teu campo, conecta com setas, indica + ou -. fica feio? tudo bem. fica útil? sim.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8bfb2523-7c75-4436-859b-1cc0a547cfd0', 4, 'exercicio_pbl', 'exercício · 1 mapa sistêmico', 'desenha o mapa do teu problema com pelo menos 5 elementos e 5 setas. fotografa e publica.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('8bfb2523-7c75-4436-859b-1cc0a547cfd0', 5, 'registro', 'registro', 'que ponto desse mapa, se mexido, mudaria muita coisa?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ffa5a6e4-a143-4934-9cd7-d730bdb41d87', 1, 'pilula_a', 'pessoas, não estatística', 'quem sente, quem decide, quem produz, quem descarta. cada um tem nome, rosto, motivação. não cabe em planilha.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ffa5a6e4-a143-4934-9cd7-d730bdb41d87', 2, 'pilula_b', 'mapa de atores', 'lista quem tá envolvido. coloca em 4 quadrantes: alta influência/baixo interesse, alta/alta, baixa/alta, baixa/baixa. estratégia muda em cada.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ffa5a6e4-a143-4934-9cd7-d730bdb41d87', 3, 'pilula_c', 'aliados e bloqueios', 'quem te ajudaria? quem resistiria? por quê? entender os 2 lados evita atropelar e perder rapport.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ffa5a6e4-a143-4934-9cd7-d730bdb41d87', 4, 'exercicio_pbl', 'exercício · meu mapa de atores', 'lista 8-12 atores do teu campo. coloca no quadrante. marca com cor: aliado provável, neutro, possível bloqueio. publica.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ffa5a6e4-a143-4934-9cd7-d730bdb41d87', 5, 'registro', 'registro', 'qual ator tu tinha esquecido? quem é peça-chave que tu não tinha visto?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('aad1f76b-4926-42a2-9525-0dde21769f2a', 1, 'pilula_a', 'a regra: 5 conversas', 'antes de propor solução, conversa com 5 pessoas do campo. parece pouco mas já mostra padrão. mais que isso vira pesquisa, menos vira chute.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('aad1f76b-4926-42a2-9525-0dde21769f2a', 2, 'pilula_b', 'pergunta aberta vence pergunta fechada', '"como tu lida com X?" rende mais que "tu acha que X é problema?". evita perguntar sobre futuro hipotético, foca no que já aconteceu.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('aad1f76b-4926-42a2-9525-0dde21769f2a', 3, 'pilula_c', 'escutar mais, falar menos', 'meta: 80% do tempo é a pessoa falando. silêncio incomoda mas faz a pessoa aprofundar. resiste à vontade de "ajudar".', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('aad1f76b-4926-42a2-9525-0dde21769f2a', 4, 'exercicio_pbl', 'exercício · 5 conversas', 'agenda e roda 5 conversas de 20 minutos com pessoas do teu campo. anota achados. junta num doc curto.', 100, 140, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('aad1f76b-4926-42a2-9525-0dde21769f2a', 5, 'registro', 'registro', 'qual frase escutada vai te acompanhar? por quê?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d31b1dd2-e396-4cd7-b6e0-3cb7f3a9341a', 1, 'pilula_a', 'hipótese é palpite testável', 'não é certeza. é "eu acho que X acontece porque Y, e isso impacta Z". escrita assim, dá pra testar e ajustar.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d31b1dd2-e396-4cd7-b6e0-3cb7f3a9341a', 2, 'pilula_b', 'o template', '"para [persona], o problema [problema] acontece quando [contexto], porque [causa provável], gerando [impacto]". formato simples, força clareza.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d31b1dd2-e396-4cd7-b6e0-3cb7f3a9341a', 3, 'pilula_c', 'boa hipótese é específica', 'evita "todo jovem", "muitas pessoas", "as vezes". usa nome, número, situação concreta. especificidade aumenta chance de acertar a solução.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d31b1dd2-e396-4cd7-b6e0-3cb7f3a9341a', 4, 'exercicio_pbl', 'exercício · minha hipótese', 'escreve tua hipótese no template. publica. pede a 2 colegas pra te dizer o que ainda está vago.', 20, 35, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d31b1dd2-e396-4cd7-b6e0-3cb7f3a9341a', 5, 'registro', 'registro', 'o que tu refinaria depois do feedback dos colegas?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('36a1a1fb-9934-4562-83d0-96aab209bda8', 1, 'pilula_a', 'o que é regenerativo', 'além de não destruir, regenera. devolve mais do que tira. solo melhor, comunidade mais forte, ar mais limpo. é a fronteira da circular.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('36a1a1fb-9934-4562-83d0-96aab209bda8', 2, 'pilula_b', '5 referências brasileiras', 'mostra 5 cases reais (banco junto, copabase, asilo da casinha, instituto akatu, banco palmas). diversidade de setor.', 6, 9, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('36a1a1fb-9934-4562-83d0-96aab209bda8', 3, 'pilula_c', 'o que copiar, o que adaptar', 'cada referência tem mecanismo próprio (modelo, parceria, comunicação). estuda o mecanismo, não a aparência.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('36a1a1fb-9934-4562-83d0-96aab209bda8', 4, 'exercicio_pbl', 'exercício · 1 referência destrinchada', 'escolhe 1 das 5 (ou outra que tu conheça). responde: qual problema, qual mecanismo, o que tu rouba pra teu projeto. 1 página.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('36a1a1fb-9934-4562-83d0-96aab209bda8', 5, 'registro', 'registro', 'o que dessa referência tu quer trazer pra tua proposta?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('726687a4-df3f-4e34-b6af-5cb4f59014ff', 1, 'pilula_a', 'quantidade antes de qualidade', 'as primeiras 5 ideias são óbvias. as boas aparecem da 10 em diante. resiste o impulso de filtrar cedo.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('726687a4-df3f-4e34-b6af-5cb4f59014ff', 2, 'pilula_b', 'técnicas que destravam', 'crazy 8s (8 ideias em 8 minutos), and/or (combina 2 ideias soltas), pior ideia possível (inverte e tira insight). uso rápido.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('726687a4-df3f-4e34-b6af-5cb4f59014ff', 3, 'pilula_c', 'sozinho rende, em grupo brilha', 'gera sozinho primeiro, traz pro grupo depois. evita pensamento de manada e protege ideia esquisita que pode ser a melhor.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('726687a4-df3f-4e34-b6af-5cb4f59014ff', 4, 'exercicio_pbl', 'exercício · 20 ideias em 20 minutos', 'pra tua hipótese de problema, gera 20 ideias diferentes em 20 minutos cronometrados. inclui 3 absurdas. publica a lista.', 25, 35, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('726687a4-df3f-4e34-b6af-5cb4f59014ff', 5, 'registro', 'registro', 'qual ideia tu nunca diria em voz alta mas te interessa?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ac6945a0-d7b5-41f5-b4b2-eea8c092bd51', 1, 'pilula_a', 'o que é proposta de valor', 'frase curta que explica: pra quem, qual problema resolve, como, e o que muda. clareza vence elaboração.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ac6945a0-d7b5-41f5-b4b2-eea8c092bd51', 2, 'pilula_b', 'camada circular', 'além do valor pra usuário, qual valor pro sistema (menos resíduo, regeneração, comunidade). 2 camadas, 1 frase só.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ac6945a0-d7b5-41f5-b4b2-eea8c092bd51', 3, 'pilula_c', 'o template', '"para [persona], que [problema], oferecemos [solução] que [benefício circular] enquanto [benefício pessoal]".', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ac6945a0-d7b5-41f5-b4b2-eea8c092bd51', 4, 'exercicio_pbl', 'exercício · minha proposta', 'escreve tua proposta no template. testa em voz alta com 1 pessoa fora do projeto. ajusta. publica.', 20, 35, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ac6945a0-d7b5-41f5-b4b2-eea8c092bd51', 5, 'registro', 'registro', 'o que ficou mais nítido depois de explicar pra alguém?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('0b394fff-3c00-4d18-860c-25390e28cceb', 1, 'pilula_a', 'mesmo projeto social precisa rodar', 'sem economia rodando, projeto bom morre em 6 meses. pensar grana cedo é parte do design, não traição da causa.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('0b394fff-3c00-4d18-860c-25390e28cceb', 2, 'pilula_b', 'canvas de 1 página', 'persona, proposta, canal, receita, custo, parceria-chave. 6 caixas, 1 página, suficiente pra começar.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('0b394fff-3c00-4d18-860c-25390e28cceb', 3, 'pilula_c', 'modelos circulares', 'aluguel em vez de venda, recompra, marketplace de descarte, taxa de uso, assinatura pra refil. menu pra inspirar.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('0b394fff-3c00-4d18-860c-25390e28cceb', 4, 'exercicio_pbl', 'exercício · meu canvas', 'preenche o canvas de 1 página da tua proposta. 6 caixas. publica como foto ou pdf.', 30, 45, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('0b394fff-3c00-4d18-860c-25390e28cceb', 5, 'registro', 'registro', 'qual caixa tu mais sentiu insegurança? o que falta investigar?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('91e30f31-0e92-4b6e-9d60-70815b490650', 1, 'pilula_a', 'protótipo barato vence ideia rica', 'antes de gastar tempo construindo, faz protótipo de papel. caneta, papel, post-it. 30 minutos rende mais que 3 dias.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('91e30f31-0e92-4b6e-9d60-70815b490650', 2, 'pilula_b', 'o que mostrar no protótipo', 'fluxo principal, 3 a 5 telas (se for app) ou jornada principal (se for serviço). foco no essencial.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('91e30f31-0e92-4b6e-9d60-70815b490650', 3, 'pilula_c', 'teste de 5 minutos', 'mostra pra 1 pessoa. ela navega no papel. tu observa onde ela trava. ajusta no próprio papel. repete.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('91e30f31-0e92-4b6e-9d60-70815b490650', 4, 'exercicio_pbl', 'exercício · meu protótipo de papel', 'desenha teu protótipo. testa com 2 pessoas. fotografa o "antes" e o "depois". publica.', 40, 60, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('91e30f31-0e92-4b6e-9d60-70815b490650', 5, 'registro', 'registro', 'o que mudou entre o primeiro e o segundo teste?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7160cf7c-e416-4122-bb77-b6958c3171b0', 1, 'pilula_a', 'teste é experimento, não vendagem', 'objetivo é aprender, não convencer. se a pessoa não gostou, é dado bom. evita defender a ideia.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7160cf7c-e416-4122-bb77-b6958c3171b0', 2, 'pilula_b', 'o roteiro do teste', 'apresenta o problema (não a solução). mostra o protótipo. pede pra pessoa narrar o que pensa enquanto usa. observa em silêncio.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7160cf7c-e416-4122-bb77-b6958c3171b0', 3, 'pilula_c', 'escutando o que não foi dito', 'pausa, dúvida, expressão de cara. o corpo conta o que a boca não diz. anota isso também.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7160cf7c-e416-4122-bb77-b6958c3171b0', 4, 'exercicio_pbl', 'exercício · 3 testes', 'roda 3 sessões de 20 minutos cada com pessoas diferentes do teu campo. organiza achados em 1 doc.', 70, 100, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('7160cf7c-e416-4122-bb77-b6958c3171b0', 5, 'registro', 'registro', 'o que tu não esperava ouvir? o que confirmou tua intuição?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('cc641e88-9f76-4e9d-836f-d85355d6d6c6', 1, 'pilula_a', 'iteração é regra, não exceção', 'primeira versão sempre erra em algo. iterar é o trabalho. quem entrega na primeira tentativa não testou direito.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('cc641e88-9f76-4e9d-836f-d85355d6d6c6', 2, 'pilula_b', 'ordem dos ajustes', 'o que bloqueia uso entra primeiro. depois o que confunde. depois o que melhoraria. resiste a mexer no que tá ok.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('cc641e88-9f76-4e9d-836f-d85355d6d6c6', 3, 'pilula_c', 'o que NÃO mudar', 'nem todo feedback vira mudança. se 1 pessoa pediu mas vai contra o problema central, tu agradece e segue.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('cc641e88-9f76-4e9d-836f-d85355d6d6c6', 4, 'exercicio_pbl', 'exercício · v2 do protótipo', 'aplica 5 ajustes prioritários no teu protótipo. testa de novo com 2 pessoas. compara reação com a v1.', 50, 75, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('cc641e88-9f76-4e9d-836f-d85355d6d6c6', 5, 'registro', 'registro', 'o que tu mudou? o que tu deixou como estava? por quê?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('1ebb9978-9dc5-4d23-abec-0b0e4cae19b1', 1, 'pilula_a', 'impacto não é vaidade', 'curtida, view, número de seguidor não é impacto. impacto é mudança no problema original. nem sempre dá pra medir, mas dá pra observar.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('1ebb9978-9dc5-4d23-abec-0b0e4cae19b1', 2, 'pilula_b', '3 níveis de medição', 'output (o que tu fez), outcome (o que mudou pro usuário), impact (o que mudou no sistema). cada um pede ferramenta diferente.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('1ebb9978-9dc5-4d23-abec-0b0e4cae19b1', 3, 'pilula_c', 'métricas circulares', 'kg de resíduo evitado, número de pessoas alcançadas, ciclos de uso por produto. simples e rastreável vence métrica linda mas inviável.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('1ebb9978-9dc5-4d23-abec-0b0e4cae19b1', 4, 'exercicio_pbl', 'exercício · meu painel de impacto', 'escolhe 3 métricas (1 output, 1 outcome, 1 tentativa de impact). define como vai medir cada uma. publica.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('1ebb9978-9dc5-4d23-abec-0b0e4cae19b1', 5, 'registro', 'registro', 'que número, se subir, tu vai considerar vitória de verdade?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('40b59625-6a4f-443a-8343-43b75248d7ef', 1, 'pilula_a', 'depois da eletiva, e aí', 'fim de aula não é fim de projeto. quem segue, multiplica. quem para, dissolve. plano simples evita o segundo destino.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('40b59625-6a4f-443a-8343-43b75248d7ef', 2, 'pilula_b', 'o plano em 1 página', '3 grandes objetivos pros próximos 90 dias. pra cada, 3 ações concretas. data, responsável, métrica. uma página, sem invento.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('40b59625-6a4f-443a-8343-43b75248d7ef', 3, 'pilula_c', 'aliados pra manter o ritmo', 'sozinho dificilmente segue. lista 2-3 pessoas que vão te cobrar. combina ritual de check-in (whatsapp semanal já basta).', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('40b59625-6a4f-443a-8343-43b75248d7ef', 4, 'exercicio_pbl', 'exercício · meu plano de 90 dias', 'monta tua página única com objetivos, ações, responsáveis. compartilha com pelo menos 1 aliado. publica.', 30, 45, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('40b59625-6a4f-443a-8343-43b75248d7ef', 5, 'registro', 'registro', 'qual ação dessa página tu vai começar essa semana?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('97616f0b-22b2-4200-a85c-ac987b23dfa1', 1, 'pilula_a', 'o dossiê em 5 partes', 'campo, problema, hipótese, proposta, achados de teste, plano de continuidade. 5 a 8 páginas, foto e gráfico permitidos.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('97616f0b-22b2-4200-a85c-ac987b23dfa1', 2, 'pilula_b', 'o pitch de 3 minutos', 'problema (30s) → quem sofre (30s) → tua proposta (60s) → achados de teste (30s) → próximos passos (30s). 3 minutos contados.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('97616f0b-22b2-4200-a85c-ac987b23dfa1', 3, 'pilula_c', 'caprichando na história', 'começa com cena concreta da persona, não com gráfico. dado entra pra confirmar, não pra abrir. emoção primeiro, dado depois.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('97616f0b-22b2-4200-a85c-ac987b23dfa1', 4, 'exercicio_pbl', 'exercício · entrega final', 'finaliza dossiê + grava pitch de 3 minutos em vídeo. envia os 2 links no formulário de entrega.', 90, 150, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('97616f0b-22b2-4200-a85c-ac987b23dfa1', 5, 'registro', 'registro', 'olhando do começo ao fim: o que mudou em ti?', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('47d80af7-2ab5-45eb-8342-450d9d4b2ec4', 1, 'pilula_a', 'o que mudou', 'a IA virou ferramenta de fazer, não só de pesquisar. quem aprende a usar agora sai na frente. nesse módulo a gente abre o jogo: por que essa eletiva existe, o que tu vai construir, como funciona o ritmo das semanas.', 4, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('47d80af7-2ab5-45eb-8342-450d9d4b2ec4', 2, 'pilula_b', 'o que tu vai entregar', 'até o fim da eletiva tu vai ter um app rodando, testado com gente real, resolvendo um problema que tu escolheu. não é exercício de aula. é projeto de verdade.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('47d80af7-2ab5-45eb-8342-450d9d4b2ec4', 3, 'pilula_c', 'como vamos andar', '4 trilhas: fundamentos, problema, construção, validação. cada semana 1 módulo novo, 5 pílulas curtas, 1 exercício prático. aproveita o ritmo, não acumula.', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('47d80af7-2ab5-45eb-8342-450d9d4b2ec4', 4, 'exercicio_pbl', 'exercício · me apresenta', 'em 1 parágrafo: quem é tu, o que faz, e qual problema do teu dia a dia tu gostaria de resolver com IA. envia no link abaixo.', 10, 15, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('47d80af7-2ab5-45eb-8342-450d9d4b2ec4', 5, 'registro', 'registro', 'o que tu espera dessa eletiva? o que te faria sair daqui dizendo "valeu cada minuto"?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5f394184-5189-45be-99f4-95c1f27e27d3', 1, 'pilula_a', 'o que é um prompt', 'prompt é instrução. quanto mais clara a intenção, melhor a resposta. a máquina não adivinha contexto, ela responde o que tu der.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5f394184-5189-45be-99f4-95c1f27e27d3', 2, 'pilula_b', 'os 4 pilares de um bom prompt', 'papel (quem a IA é), tarefa (o que fazer), contexto (pra quem, em que situação) e formato (como entregar). teste num prompt fraco, depois aplica os 4.', 6, 10, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5f394184-5189-45be-99f4-95c1f27e27d3', 3, 'pilula_c', 'iteração: prompt nunca nasce pronto', 'primeira resposta raramente é a melhor. refina, dá exemplo, corrige rumo. é conversa, não comando único.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5f394184-5189-45be-99f4-95c1f27e27d3', 4, 'exercicio_pbl', 'exercício · refazendo um prompt teu', 'pega uma pergunta que tu fez pra IA recentemente. reescreve usando os 4 pilares. compara as duas respostas e anota o que mudou.', 15, 25, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5f394184-5189-45be-99f4-95c1f27e27d3', 5, 'registro', 'registro', 'qual diferença tu sentiu entre o prompt antigo e o novo? o que tu vai levar pra próxima conversa?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('a581c83f-1742-4205-b5a1-25fac1054a07', 1, 'pilula_a', 'os modelos do mercado', 'gpt, claude, gemini, llama. cada um tem força diferente: raciocínio, criatividade, código, contexto longo. saber escolher economiza tempo.', 6, 9, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('a581c83f-1742-4205-b5a1-25fac1054a07', 2, 'pilula_b', 'quando usar cada um', 'gemini é rápido e barato pra tarefa simples. claude brilha em texto longo e nuance. gpt é generalista forte. testa os 3 no mesmo prompt e sente.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('a581c83f-1742-4205-b5a1-25fac1054a07', 3, 'pilula_c', 'multimodal: texto, imagem, voz, código', 'modelos modernos leem imagem, geram código, conversam por voz. abre possibilidades que prompt-só-texto não abre.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('a581c83f-1742-4205-b5a1-25fac1054a07', 4, 'exercicio_pbl', 'exercício · benchmark pessoal', 'escolhe uma tarefa real (resumir um pdf, escrever um e-mail difícil, gerar uma ideia). roda nos 3 modelos. anota qual ganhou e por quê.', 15, 25, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('a581c83f-1742-4205-b5a1-25fac1054a07', 5, 'registro', 'registro', 'qual modelo virou teu padrão? em que situação tu trocaria?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d1b73633-c4bd-4823-b816-c18bab721d37', 1, 'pilula_a', 'o que é no-code', 'ferramentas que deixam tu construir software sem escrever código. arrasta, conecta, configura. democratizou criar app.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d1b73633-c4bd-4823-b816-c18bab721d37', 2, 'pilula_b', 'panorama das ferramentas', 'lovable, bubble, webflow, glide, n8n. cada uma serve um tipo de problema. lovable é IA-first pra app web.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d1b73633-c4bd-4823-b816-c18bab721d37', 3, 'pilula_c', 'low-code é meio termo', 'tu escreve um pouco, mas a IA preenche o resto. ganha velocidade sem perder controle. é o caminho que a maioria vai trilhar.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d1b73633-c4bd-4823-b816-c18bab721d37', 4, 'exercicio_pbl', 'exercício · explora 2 ferramentas', 'abre lovable e mais uma (bubble ou glide). cria a tela inicial de uma ideia tua nas duas. compara: qual te deu mais flow?', 20, 30, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('d1b73633-c4bd-4823-b816-c18bab721d37', 5, 'registro', 'registro', 'no-code resolve tudo? onde tu acha que ainda precisa de programador de verdade?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('942c4d2a-820c-4b83-8685-754982f8aa1f', 1, 'pilula_a', 'o que é o lovable', 'IDE que conversa em português e constrói app web em react. tu descreve, ele faz. tu pede pra ajustar, ele ajusta.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('942c4d2a-820c-4b83-8685-754982f8aa1f', 2, 'pilula_b', 'o ciclo de construção', 'prompt → preview → testa → refina. o segredo é prompt curto e iteração rápida, não prompt gigante de uma vez.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('942c4d2a-820c-4b83-8685-754982f8aa1f', 3, 'pilula_c', 'os superpoderes: cloud, ai, integrações', 'lovable cloud dá banco e auth de graça. ai gateway dá llm sem api key. integrações nativas (stripe, twilio, slack). não precisa montar stack.', 6, 9, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('942c4d2a-820c-4b83-8685-754982f8aa1f', 4, 'exercicio_pbl', 'exercício · primeiro app', 'abre o lovable, cria projeto novo. pede uma landing page de 1 produto fictício teu. publica e manda o link.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('942c4d2a-820c-4b83-8685-754982f8aa1f', 5, 'registro', 'registro', 'qual foi a maior surpresa? o que tu pediu e ele entregou diferente?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('361bbbd1-b551-472f-9a9b-a5387f12ea9a', 1, 'pilula_a', 'problema bom vs problema ruim', 'problema bom é específico, dói em alguém de verdade, e é frequente. problema ruim é genérico ou inventado.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('361bbbd1-b551-472f-9a9b-a5387f12ea9a', 2, 'pilula_b', 'como caçar problema na vida real', 'observa o que te irrita, o que tua família reclama, o que teu professor xinga. problema vive em fricção do cotidiano.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('361bbbd1-b551-472f-9a9b-a5387f12ea9a', 3, 'pilula_c', 'a regra da dor real', 'se a pessoa não ia pagar (com tempo, dinheiro ou atenção) pra resolver, talvez não seja problema, seja incômodo.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('361bbbd1-b551-472f-9a9b-a5387f12ea9a', 4, 'exercicio_pbl', 'exercício · lista de 10 problemas', 'anota 10 problemas que tu observou nos últimos 7 dias. teus, dos teus pais, dos teus colegas. sem filtrar. quantidade primeiro.', 15, 25, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('361bbbd1-b551-472f-9a9b-a5387f12ea9a', 5, 'registro', 'registro', 'qual desses 10 te chamou mais atenção? por quê?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('67c91f7b-c7e5-405c-8a95-572a6c9e1997', 1, 'pilula_a', 'os 3 critérios', 'paixão (tu se importa?), viabilidade (dá pra resolver com app?), impacto (resolve a vida de alguém?). os 3 juntos é zona de ouro.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('67c91f7b-c7e5-405c-8a95-572a6c9e1997', 2, 'pilula_b', 'matar darlings', 'vai sobrar problema bom que tu não vai pegar. tudo bem. escolher é abrir mão. fica com 1 só.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('67c91f7b-c7e5-405c-8a95-572a6c9e1997', 3, 'pilula_c', 'teste do elevador', 'consegue descrever o problema em 2 frases pra alguém que não conhece? se enrola, ainda não entendeu o suficiente.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('67c91f7b-c7e5-405c-8a95-572a6c9e1997', 4, 'exercicio_pbl', 'exercício · escolhe e defende', 'da tua lista de 10, escolhe 1. escreve em 3 frases: qual o problema, quem sente, por que importa. publica no link.', 15, 25, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('67c91f7b-c7e5-405c-8a95-572a6c9e1997', 5, 'registro', 'registro', 'por que esse e não outro? o que te puxou?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bc3d84e2-1765-4610-8b6e-cdae03c83454', 1, 'pilula_a', 'persona não é avatar genérico', 'persona é uma pessoa específica que sente o problema. nome, idade, rotina, frustração concreta. quanto mais real, melhor o app fica.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bc3d84e2-1765-4610-8b6e-cdae03c83454', 2, 'pilula_b', 'jobs to be done', 'a pessoa não quer teu app. ela quer resolver uma situação. entende o "trabalho" que ela contrataria teu app pra fazer.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bc3d84e2-1765-4610-8b6e-cdae03c83454', 3, 'pilula_c', 'contexto importa mais que demografia', 'idade e cidade ajudam pouco. saber em que momento, com que celular, com quanto tempo, importa muito.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bc3d84e2-1765-4610-8b6e-cdae03c83454', 4, 'exercicio_pbl', 'exercício · ficha da persona', 'preenche: nome, idade, rotina típica, momento em que sente o problema, o que ela faz hoje pra contornar. 1 página.', 15, 25, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bc3d84e2-1765-4610-8b6e-cdae03c83454', 5, 'registro', 'registro', 'qual descoberta sobre tua persona te surpreendeu?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('9bd231d6-fbec-4735-995e-48004c336453', 1, 'pilula_a', 'mvp não é app inteiro', 'mvp = mínimo produto viável. menor coisa que resolve o problema central pra 1 pessoa. tudo mais fica pra depois.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('9bd231d6-fbec-4735-995e-48004c336453', 2, 'pilula_b', 'feature creep mata projeto', 'cada feature nova é mais bug, mais tempo, mais confusão. a tentação de "só mais uma coisinha" atrasa a entrega.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('9bd231d6-fbec-4735-995e-48004c336453', 3, 'pilula_c', 'a régua do escopo', 'pergunta: sem essa feature, o problema central ainda é resolvido? se sim, fica pra v2. se não, entra no mvp.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('9bd231d6-fbec-4735-995e-48004c336453', 4, 'exercicio_pbl', 'exercício · in/out', 'lista 10 features que tu imaginou pro app. escolhe 3 pra dentro do mvp. justifica por que as outras 7 ficam fora.', 15, 25, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('9bd231d6-fbec-4735-995e-48004c336453', 5, 'registro', 'registro', 'qual feature foi mais difícil deixar de fora? por quê?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('2697ad76-339e-4c0c-b6c2-2f8091ab1f13', 1, 'pilula_a', 'estrutura do pitch', 'problema (10s) → quem sofre (10s) → tua solução (20s) → por que tu (10s) → call to action (10s). 60 segundos contados.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('2697ad76-339e-4c0c-b6c2-2f8091ab1f13', 2, 'pilula_b', 'contar história, não recitar specs', 'comece com cena concreta da persona. desperta empatia antes de explicar feature. técnica do storytelling vence apresentação fria.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('2697ad76-339e-4c0c-b6c2-2f8091ab1f13', 3, 'pilula_c', 'palavras que pegam, palavras que somem', 'corta jargão, advérbio e qualquer "muito". usa verbo forte. ouve gravando tua voz e edita.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('2697ad76-339e-4c0c-b6c2-2f8091ab1f13', 4, 'exercicio_pbl', 'exercício · grava teu pitch', 'escreve, decora, grava em vídeo de 60s no celular. assiste com som, depois sem som. publica o link.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('2697ad76-339e-4c0c-b6c2-2f8091ab1f13', 5, 'registro', 'registro', 'o que tu mudaria se tivesse 30s a mais? e se tivesse 30s a menos?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('3ef444a1-ac29-470f-aaaf-87be5176a718', 1, 'pilula_a', 'briefing pro lovable', 'descreve o app em 1 parágrafo: o que faz, pra quem, telas principais, fluxo principal. evita jargão técnico.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('3ef444a1-ac29-470f-aaaf-87be5176a718', 2, 'pilula_b', 'primeira tela importa', 'a tela inicial define a percepção. lovable usa esse prompt como base de tudo. capricha aqui e ganha tempo depois.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('3ef444a1-ac29-470f-aaaf-87be5176a718', 3, 'pilula_c', 'iteração rápida', 'roda, vê, ajusta. não tenta acertar de primeira. cada ciclo de 5 minutos te aproxima do mlp.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('3ef444a1-ac29-470f-aaaf-87be5176a718', 4, 'exercicio_pbl', 'exercício · primeira versão no ar', 'abre lovable, cola teu briefing, gera as 3 telas principais. publica e compartilha o link com 1 colega.', 30, 50, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('3ef444a1-ac29-470f-aaaf-87be5176a718', 5, 'registro', 'registro', 'o que ficou diferente do que tu imaginou? o que ficou melhor?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('4122216b-c508-4b87-8584-1d727045afe9', 1, 'pilula_a', 'mvp vs mlp', 'mvp = funciona. mlp (minimum lovable product) = funciona e a pessoa ama usar. a diferença está no detalhe de ux.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('4122216b-c508-4b87-8584-1d727045afe9', 2, 'pilula_b', 'o que polir primeiro', 'fluxo principal end-to-end sem bug. depois copy. depois visual. ordem importa pra não perder tempo com cor antes de ter botão certo.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('4122216b-c508-4b87-8584-1d727045afe9', 3, 'pilula_c', 'feedback de 3 pessoas', 'mostra pra 3 conhecidos. olha onde travam, escuta o que perguntam, anota o que reclamam. 3 já mostra padrão.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('4122216b-c508-4b87-8584-1d727045afe9', 4, 'exercicio_pbl', 'exercício · 3 ciclos de iteração', 'pega 1 reclamação concreta de cada pessoa. no lovable, ajusta. publica de novo. anota o que mudou.', 30, 45, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('4122216b-c508-4b87-8584-1d727045afe9', 5, 'registro', 'registro', 'qual ajuste pequeno fez maior diferença na percepção?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bebadf19-1b34-4900-a32e-157464575211', 1, 'pilula_a', 'ux é como a pessoa sente, não o que tu desenha', 'bom ux é invisível. a pessoa usa sem pensar. ruim é quando ela trava ou pergunta "como faço".', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bebadf19-1b34-4900-a32e-157464575211', 2, 'pilula_b', 'mobile-first não é opcional', 'adolescente vive no celular. se não funciona bem em tela pequena, não funciona. testa no teu celular antes do desktop.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bebadf19-1b34-4900-a32e-157464575211', 3, 'pilula_c', 'copy é parte da ux', 'botão que diz "salvar rascunho" comunica melhor que "ok". toast diz o que aconteceu e qual o próximo passo.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bebadf19-1b34-4900-a32e-157464575211', 4, 'exercicio_pbl', 'exercício · audita teu app', 'abre teu app no celular. percorre o fluxo principal. anota 5 lugares onde tu travou ou ficou na dúvida. corrige no lovable.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('bebadf19-1b34-4900-a32e-157464575211', 5, 'registro', 'registro', 'qual ajuste de copy ou layout deixou tudo mais natural?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('226eb31f-955e-49b8-a95b-b3463444e9dc', 1, 'pilula_a', 'quando IA agrega, quando atrapalha', 'IA boa resolve problema que sem ela seria chato. IA decorativa só engorda o app. pergunta: precisa mesmo?', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('226eb31f-955e-49b8-a95b-b3463444e9dc', 2, 'pilula_b', 'lovable ai gateway', 'gateway que dá acesso a gemini, gpt, claude sem api key tua. configurar é 2 cliques. usar é 1 chamada de função.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('226eb31f-955e-49b8-a95b-b3463444e9dc', 3, 'pilula_c', 'padrões úteis', 'classificação, geração de texto, sumarização, busca semântica, conversa. 90% dos casos cabem aqui. evita reinventar.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('226eb31f-955e-49b8-a95b-b3463444e9dc', 4, 'exercicio_pbl', 'exercício · adiciona 1 feature de IA', 'pensa em 1 momento do teu app onde IA tira fricção (resumir, sugerir, traduzir, responder). implementa pelo lovable.', 30, 50, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('226eb31f-955e-49b8-a95b-b3463444e9dc', 5, 'registro', 'registro', 'a IA virou parte central ou só decoração? o usuário ia notar se sumisse?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ed7d95bf-3c5d-4db5-b0f6-8d398d6a911d', 1, 'pilula_a', 'o que é teste de fumaça', 'teste rápido pra ver se nada óbvio quebra. percorre o fluxo principal de ponta a ponta antes de mostrar pra alguém.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ed7d95bf-3c5d-4db5-b0f6-8d398d6a911d', 2, 'pilula_b', 'checklist mental', 'cadastro funciona? login funciona? ação principal funciona? sai sem erro? abre no celular alheio?', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ed7d95bf-3c5d-4db5-b0f6-8d398d6a911d', 3, 'pilula_c', 'quem testa não pode ser tu', 'tu já sabe demais. pega alguém que nunca viu. observa em silêncio. anota cada hesitação.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ed7d95bf-3c5d-4db5-b0f6-8d398d6a911d', 4, 'exercicio_pbl', 'exercício · 1 sessão de teste', 'pega 1 pessoa não-técnica. dá o link sem instrução. cronometra quanto tempo até completar a ação principal. anota onde travou.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('ed7d95bf-3c5d-4db5-b0f6-8d398d6a911d', 5, 'registro', 'registro', 'o que ficou claro que tu não tinha visto sozinho?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('6b949595-35d0-4a82-acef-af76207bae02', 1, 'pilula_a', 'mvt = minimum viable test', 'depois do mlp, a próxima fronteira é provar que resolve mesmo. mvt é a versão pronta pra ser testada com público real.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('6b949595-35d0-4a82-acef-af76207bae02', 2, 'pilula_b', 'preparando pra teste real', 'tem texto de boas-vindas? tem onde a pessoa deixa contato? tu consegue medir se ela usou? sem isso o teste é cego.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('6b949595-35d0-4a82-acef-af76207bae02', 3, 'pilula_c', 'métricas que importam', 'ativação (chegou e usou?), retenção (voltou?), satisfação (recomendaria?). 3 números resolvem a maioria das perguntas.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('6b949595-35d0-4a82-acef-af76207bae02', 4, 'exercicio_pbl', 'exercício · prepara teu mvt', 'lista 3 métricas que tu vai acompanhar. configura um jeito simples (analytics, formulário, contador). publica versão de teste.', 25, 40, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('6b949595-35d0-4a82-acef-af76207bae02', 5, 'registro', 'registro', 'o que tu vai considerar "deu certo" depois do teste?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('73eb6207-8fab-4c86-843d-671ee1a4963c', 1, 'pilula_a', 'como recrutar 5 pessoas', 'pede no whatsapp, no insta, na escola. 5 chega. mais que isso, vira sobrecarga de feedback. menos, vira amostra ruim.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('73eb6207-8fab-4c86-843d-671ee1a4963c', 2, 'pilula_b', 'o roteiro do teste', 'apresenta o problema (não a solução). manda o link. pede pra falar em voz alta o que está pensando. observa em silêncio.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('73eb6207-8fab-4c86-843d-671ee1a4963c', 3, 'pilula_c', 'separa sinal de ruído', 'opinião de pessoa não importa. comportamento sim. o que ela disse pode ser educação. o que ela fez é verdade.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('73eb6207-8fab-4c86-843d-671ee1a4963c', 4, 'exercicio_pbl', 'exercício · 5 testes em 1 semana', 'agenda 5 sessões de 15 minutos cada. grava (com permissão) ou anota. junta os achados num documento curto.', 60, 90, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('73eb6207-8fab-4c86-843d-671ee1a4963c', 5, 'registro', 'registro', 'qual achado mais te surpreendeu? confirmou ou contradisse tua hipótese?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('fae80761-2d90-4296-a3fb-e68762f58951', 1, 'pilula_a', 'feedback é dado, não verdade', 'cada feedback é uma pista. 1 pessoa = sinal fraco. 3 pessoas dizendo igual = padrão. olha pra padrão, não pra opinião isolada.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('fae80761-2d90-4296-a3fb-e68762f58951', 2, 'pilula_b', 'priorizar ajustes', 'ordena: o que bloqueia uso, o que confunde, o que melhoraria. resolve nessa ordem. não trata tudo igual.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('fae80761-2d90-4296-a3fb-e68762f58951', 3, 'pilula_c', 'o que NÃO mudar', 'às vezes a pessoa pede o que ia te tirar do rumo. nem todo pedido vira feature. mantém o foco do problema central.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('fae80761-2d90-4296-a3fb-e68762f58951', 4, 'exercicio_pbl', 'exercício · 2 ciclos de ajuste', 'do teu doc de feedback, escolhe 5 ajustes prioritários. faz no lovable em 2 ciclos curtos. publica versão final pra entrega.', 40, 60, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('fae80761-2d90-4296-a3fb-e68762f58951', 5, 'registro', 'registro', 'o que tu mudou? o que tu decidiu deixar como estava? por quê?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5897e94e-06e3-4245-a51d-19ba144ca67e', 1, 'pilula_a', 'o que vai compor tua entrega', 'app publicado + pitch de 60s + dossiê curto (problema, persona, decisões, aprendizados). 3 peças, simples.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5897e94e-06e3-4245-a51d-19ba144ca67e', 2, 'pilula_b', 'caprichando no pitch final', 'agora tu tem dado real. pitch ganha "rodei com 5 pessoas, 4 voltariam, 3 indicariam". virou prova, não promessa.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5897e94e-06e3-4245-a51d-19ba144ca67e', 3, 'pilula_c', 'o dossiê em 1 página', 'problema, quem sofre, o que tu construiu, o que aprendeu testando, o que vem depois. 1 página formato landscape.', 5, 8, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5897e94e-06e3-4245-a51d-19ba144ca67e', 4, 'exercicio_pbl', 'exercício · monta a entrega', 'reúne os 3 entregáveis num link só (pasta drive ou notion). manda no formulário de entrega final.', 40, 60, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('5897e94e-06e3-4245-a51d-19ba144ca67e', 5, 'registro', 'registro', 'olhando o ponto de partida e a entrega: o que mudou em ti?', 3, 5, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('13041e2b-84e7-4cc1-80d3-6a839a5fad86', 1, 'pilula_a', 'o palco final', 'tu vai apresentar pra turma e pra banca. 3 minutos por projeto. estrutura: problema → solução → demo → aprendizado.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('13041e2b-84e7-4cc1-80d3-6a839a5fad86', 2, 'pilula_b', 'demo ao vivo é arriscada', 'wifi cai, app trava, persona some. grava um vídeo de backup de 30s mostrando o fluxo principal.', 4, 6, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('13041e2b-84e7-4cc1-80d3-6a839a5fad86', 3, 'pilula_c', 'o que faz pitch final brilhar', 'energia tua + dado de teste real + clareza do problema. não é o app mais bonito que ganha, é a história mais bem contada.', 5, 7, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('13041e2b-84e7-4cc1-80d3-6a839a5fad86', 4, 'exercicio_pbl', 'exercício · ensaio final', 'ensaia o pitch 3x. cronometra. ajusta o que fica fora dos 3 minutos. grava a versão final em vídeo.', 30, 50, true, true);
INSERT INTO module_pills (module_id, order_index, kind, title, body_md, duration_min_low, duration_min_high, required, published) VALUES ('13041e2b-84e7-4cc1-80d3-6a839a5fad86', 5, 'registro', 'registro', 'o que tu vai levar dessa eletiva pro próximo projeto teu?', 5, 8, true, true);
